import { FlatCompat } from "@eslint/eslintrc";

import { baseConfig } from "@rfp-os/config/eslint";

const compat = new FlatCompat({ baseDirectory: import.meta.dirname });

const config = [
  // next-env.d.ts is generated by Next on every build (and its triple-slash
  // references trip @typescript-eslint/triple-slash-reference). Next's docs
  // say the file should not be edited, so exclude it rather than fight it.
  { ignores: ["next-env.d.ts", ".next*/**"] },
  ...baseConfig,
  ...compat.extends("next/core-web-vitals"),
];

export default config;
